-- TORVO V2 operational RPCs: inventory/reorder, requests/messages and schemes.
create or replace function submit_reorder(p_item uuid,p_required_qty numeric) returns uuid language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;v uuid;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin','store_keeper') then raise exception 'Not authorized';end if;if p_required_qty<=0 or not exists(select 1 from catalog_items where id=p_item) then raise exception 'Invalid reorder request';end if;insert into stock_reorder_requests(item_id,required_qty,submitted_by) values(p_item,p_required_qty,a.id) returning id into v;insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'REORDER_SUBMITTED','stock_reorder',v::text,jsonb_build_object('item_id',p_item,'required_qty',p_required_qty));return v;end;$$;
revoke all on function submit_reorder(uuid,numeric) from public,anon;grant execute on function submit_reorder(uuid,numeric) to authenticated;
create or replace function update_reorder_status(p_reorder uuid,p_status text) returns void language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;r stock_reorder_requests%rowtype;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin','store_keeper') then raise exception 'Not authorized';end if;if p_status not in('ordered','cancelled') then raise exception 'Invalid reorder status';end if;select * into r from stock_reorder_requests where id=p_reorder for update;if not found then raise exception 'Reorder request not found';end if;if r.status<>'submitted' then raise exception 'Only submitted reorder can be changed';end if;update stock_reorder_requests set status=p_status where id=p_reorder;insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'REORDER_STATUS_CHANGED','stock_reorder',p_reorder::text,jsonb_build_object('from',r.status,'to',p_status));end;$$;
revoke all on function update_reorder_status(uuid,text) from public,anon;grant execute on function update_reorder_status(uuid,text) to authenticated;
create or replace function receive_reorder(p_reorder uuid,p_received_qty numeric) returns numeric language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;r stock_reorder_requests%rowtype;v numeric;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin','store_keeper') then raise exception 'Not authorized';end if;if p_received_qty is null or p_received_qty<=0 then raise exception 'Received quantity must be greater than zero';end if;select * into r from stock_reorder_requests where id=p_reorder for update;if not found then raise exception 'Reorder request not found';end if;if r.status<>'ordered' then raise exception 'Only ordered stock can be received';end if;perform 1 from inventory where item_id=r.item_id for update;if not found then raise exception 'Inventory item not found';end if;update inventory set current_qty=current_qty+p_received_qty,updated_at=now() where item_id=r.item_id returning current_qty into v;update stock_reorder_requests set status='received' where id=p_reorder;insert into inventory_movements(item_id,qty_change,reason,reference_type,reference_id,created_by) values(r.item_id,p_received_qty,'Purchase / reorder received','reorder',p_reorder,a.id);insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'REORDER_RECEIVED','stock_reorder',p_reorder::text,jsonb_build_object('item_id',r.item_id,'received_qty',p_received_qty,'new_qty',v));return v;end;$$;
revoke all on function receive_reorder(uuid,numeric) from public,anon;grant execute on function receive_reorder(uuid,numeric) to authenticated;
create or replace function adjust_inventory(p_item uuid,p_qty_change numeric,p_reason text) returns numeric language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;v numeric;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin','store_keeper') then raise exception 'Not authorized';end if;if p_qty_change=0 or nullif(trim(p_reason),'') is null then raise exception 'Quantity change and reason required';end if;perform 1 from inventory where item_id=p_item for update;if not found then raise exception 'Inventory item not found';end if;select current_qty+p_qty_change into v from inventory where item_id=p_item;if v<0 then raise exception 'Stock cannot become negative';end if;update inventory set current_qty=v,updated_at=now() where item_id=p_item;insert into inventory_movements(item_id,qty_change,reason,reference_type,created_by) values(p_item,p_qty_change,trim(p_reason),'manual_adjustment',a.id);insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'INVENTORY_ADJUSTED','catalog_item',p_item::text,jsonb_build_object('qty_change',p_qty_change,'reason',trim(p_reason),'new_qty',v));return v;end;$$;
revoke all on function adjust_inventory(uuid,numeric,text) from public,anon;grant execute on function adjust_inventory(uuid,numeric,text) to authenticated;
create or replace function create_non_available_request(p_search_text text,p_item_type text default null,p_qty numeric default null) returns uuid language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;v uuid;d uuid;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found then raise exception 'Active user required';end if;if nullif(trim(p_search_text),'') is null then raise exception 'Request text required';end if;if p_item_type is not null and p_item_type not in('machine','spare_part','accessory') then raise exception 'Invalid item type';end if;if p_qty is not null and p_qty<=0 then raise exception 'Quantity must be greater than zero';end if;if a.role='dealer' then d:=current_dealer_id();if d is null then raise exception 'Approved dealer required';end if;elsif a.role not in('owner','admin','salesman') then raise exception 'Not authorized';end if;insert into non_available_requests(dealer_id,search_text,item_type,qty) values(d,trim(p_search_text),p_item_type,p_qty) returning id into v;insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'NON_AVAILABLE_REQUEST_CREATED','non_available_request',v::text,jsonb_build_object('search_text',trim(p_search_text)));return v;end;$$;
revoke all on function create_non_available_request(text,text,numeric) from public,anon;grant execute on function create_non_available_request(text,text,numeric) to authenticated;
create or replace function set_non_available_status(p_request uuid,p_status text) returns void language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;old_status text;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin','salesman') then raise exception 'Not authorized';end if;if p_status not in('reviewing','sourced','closed') then raise exception 'Invalid request status';end if;select status into old_status from non_available_requests where id=p_request for update;if not found then raise exception 'Request not found';end if;if old_status='closed' then raise exception 'Closed request cannot be changed';end if;update non_available_requests set status=p_status where id=p_request;insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'NON_AVAILABLE_STATUS_CHANGED','non_available_request',p_request::text,jsonb_build_object('from',old_status,'to',p_status));end;$$;
revoke all on function set_non_available_status(uuid,text) from public,anon;grant execute on function set_non_available_status(uuid,text) to authenticated;
create or replace function send_dealer_message(p_dealer uuid,p_subject text,p_body text) returns uuid language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;v uuid;d uuid;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found then raise exception 'Active user required';end if;if nullif(trim(p_body),'') is null then raise exception 'Message required';end if;if a.role='dealer' then d:=current_dealer_id();if d is null then raise exception 'Approved dealer required';end if;elsif a.role in('owner','admin','salesman') then d:=p_dealer;else raise exception 'Not authorized';end if;insert into messages(dealer_id,sender_id,subject,body) values(d,a.id,nullif(trim(p_subject),''),trim(p_body)) returning id into v;return v;end;$$;
revoke all on function send_dealer_message(uuid,text,text) from public,anon;grant execute on function send_dealer_message(uuid,text,text) to authenticated;
create or replace function mark_message_read(p_message uuid) returns void language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;d uuid;m messages%rowtype;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found then raise exception 'Active user required';end if;select * into m from messages where id=p_message for update;if not found then raise exception 'Message not found';end if;if a.role='dealer' then d:=current_dealer_id();if d is null or m.dealer_id is distinct from d then raise exception 'Not authorized';end if;elsif a.role not in('owner','admin','salesman') then raise exception 'Not authorized';end if;update messages set read_at=coalesce(read_at,now()) where id=p_message;end;$$;
revoke all on function mark_message_read(uuid) from public,anon;grant execute on function mark_message_read(uuid) to authenticated;
create or replace function create_scheme(p_name text,p_start date,p_end date,p_rules jsonb default '{}'::jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;v uuid;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin') then raise exception 'Not authorized';end if;if nullif(trim(p_name),'') is null or p_end<p_start then raise exception 'Invalid scheme';end if;insert into schemes(name,start_date,end_date,rules) values(trim(p_name),p_start,p_end,coalesce(p_rules,'{}'::jsonb)) returning id into v;insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'SCHEME_CREATED','scheme',v::text,jsonb_build_object('name',trim(p_name)));return v;end;$$;
revoke all on function create_scheme(text,date,date,jsonb) from public,anon;grant execute on function create_scheme(text,date,date,jsonb) to authenticated;
create or replace function add_scheme_slab(p_scheme uuid,p_min numeric,p_max numeric,p_gift text,p_points numeric default 0) returns uuid language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;v uuid;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin') then raise exception 'Not authorized';end if;if p_min<0 or(p_max is not null and p_max<p_min)or p_points<0 then raise exception 'Invalid slab';end if;insert into scheme_slabs(scheme_id,min_value,max_value,gift_name,points) values(p_scheme,p_min,p_max,nullif(trim(p_gift),''),p_points) returning id into v;return v;end;$$;
revoke all on function add_scheme_slab(uuid,numeric,numeric,text,numeric) from public,anon;grant execute on function add_scheme_slab(uuid,numeric,numeric,text,numeric) to authenticated;
